from dataclasses import dataclass
import numpy as np


@dataclass(frozen=True)
class Pair:
    winner: int
    loser: int
    weight: float = 1.0


def stable_sigmoid(x: float) -> float:
    if x >= 0:
        return 1.0 / (1.0 + np.exp(-x))
    exp_x = np.exp(x)
    return float(exp_x / (1.0 + exp_x))


def fit_scores(n_items: int, pairs: list[Pair], steps: int = 2000, lr: float = 0.05) -> np.ndarray:
    if n_items <= 0 or not pairs:
        raise ValueError("non-empty problem required")
    scores = np.zeros(n_items, dtype=np.float64)
    total_weight = sum(pair.weight for pair in pairs)
    for _ in range(steps):
        gradient = np.zeros_like(scores)
        for pair in pairs:
            if pair.weight <= 0:
                raise ValueError("weights must be positive")
            delta = scores[pair.winner] - scores[pair.loser]
            g = (stable_sigmoid(float(delta)) - 1.0) * pair.weight
            gradient[pair.winner] += g
            gradient[pair.loser] -= g
        scores -= lr * gradient / total_weight
        scores -= scores.mean()  # fixes the additive gauge
    return scores


transitive = fit_scores(3, [Pair(0, 1), Pair(1, 2)])
assert transitive[0] > transitive[1] > transitive[2]

cycle = fit_scores(3, [Pair(0, 1), Pair(1, 2), Pair(2, 0)])
assert np.allclose(cycle, 0.0, atol=1e-8)
```

Центрирование не добавляет информации. Оно выбирает удобный нуль среди эквивалентных решений.

