import numpy as np


def calibration_bins(prob: np.ndarray, label: np.ndarray, n_bins: int = 10) -> list[dict[str, float]]:
    prob = np.asarray(prob, dtype=np.float64).reshape(-1)
    label = np.asarray(label, dtype=np.float64).reshape(-1)
    if prob.shape != label.shape or prob.size == 0:
        raise ValueError("aligned non-empty arrays required")
    if np.any((prob < 0) | (prob > 1)) or np.any((label < 0) | (label > 1)):
        raise ValueError("values must lie in [0, 1]")
    if n_bins <= 0:
        raise ValueError("n_bins must be positive")
    index = np.minimum((prob * n_bins).astype(int), n_bins - 1)
    result = []
    for bin_id in range(n_bins):
        mask = index == bin_id
        if not np.any(mask):
            continue
        result.append({
            "count": float(mask.sum()),
            "mean_confidence": float(prob[mask].mean()),
            "empirical_frequency": float(label[mask].mean()),
        })
    return result


def expected_calibration_error(prob: np.ndarray, label: np.ndarray, n_bins: int = 10) -> float:
    bins = calibration_bins(prob, label, n_bins)
    total = len(np.asarray(prob).reshape(-1))
    return float(sum(
        item["count"] / total * abs(item["mean_confidence"] - item["empirical_frequency"])
        for item in bins
    ))
```

Правило `minimum(..., n_bins - 1)` помещает вероятность $1.0$ в последний интервал.
